// Build locally; visitors never download or run the Tailwind compiler.
const fs = require('node:fs/promises');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

async function iconSourceFiles(root) {
  const directories = ['.', 'services', 'villes', 'contact', 'realisations', 'merci', 'js'];
  const files = [];
  for (const directory of directories) {
    for (const entry of await fs.readdir(path.join(root, directory), { withFileTypes: true })) {
      if (entry.isFile() && /\.(html|js)$/.test(entry.name)) files.push(path.join(root, directory, entry.name));
    }
  }
  return files;
}

async function buildIcons(root, lucideRoot) {
  const iconNames = new Set();
  for (const file of await iconSourceFiles(root)) {
    const source = await fs.readFile(file, 'utf8');
    for (const match of source.matchAll(/data-lucide\s*=\s*["']([\w-]+)["']/g)) iconNames.add(match[1]);
    for (const match of source.matchAll(/setAttribute\(\s*["']data-lucide["']\s*,\s*["']([\w-]+)["']/g)) iconNames.add(match[1]);
  }
  // When adding an icon with a dynamically assembled name, add its concrete
  // names here so the build remains explicit and does not ship the whole set.
  const extraIcons = [];
  extraIcons.forEach(name => iconNames.add(name));
  const library = require('lucide');
  const icons = {};
  for (const name of [...iconNames].sort()) {
    const exportName = name.replace(/(\w)(\w*)(_|-|\s*)/g, (_, first, rest) => first.toUpperCase() + rest.toLowerCase());
    if (!library[exportName]) throw new Error(`Unknown Lucide icon: ${name}`);
    icons[exportName] = library[exportName];
  }

  // Bundle the pinned upstream renderer unchanged in behavior, with only the
  // selected icon data. No runtime compiler or extra bundler is needed.
  const stripModuleLines = source => source
    .replace(/^import .*;\n/gm, '')
    .replace(/^export .*;\n/gm, '')
    .replace(/^\/\/# sourceMappingURL=.*$/gm, '');
  const createElement = stripModuleLines(await fs.readFile(path.join(lucideRoot, 'dist/esm/createElement.js'), 'utf8'));
  const replaceElement = stripModuleLines(await fs.readFile(path.join(lucideRoot, 'dist/esm/replaceElement.js'), 'utf8'))
    .replace('createElement([tag, iconAttrs, children])', 'createElement$1([tag, iconAttrs, children])');
  const upstream = await fs.readFile(path.join(lucideRoot, 'dist/esm/lucide.js'), 'utf8');
  const start = upstream.indexOf('const createIcons =');
  const end = upstream.indexOf('export { createIcons };', start);
  if (start < 0 || end < 0) throw new Error('Lucide renderer changed; review the icon build before upgrading.');
  const createIcons = upstream.slice(start, end).replace('icons = {}', 'icons = bundledIcons');
  const bundled = `/*! Lucide v0.469.0 — ISC. See lucide-LICENSE.txt. Generated by npm run build. */\n` +
    `(() => {\nconst bundledIcons=${JSON.stringify(icons)};\n${createElement}\n${replaceElement}\n${createIcons}\nwindow.lucide = { createIcons };\n})();\n`;
  await fs.writeFile('assets/js/lucide.min.js', bundled);
  await fs.copyFile(path.join(lucideRoot, 'LICENSE'), 'assets/js/lucide-LICENSE.txt');
  console.log(`Bundled ${iconNames.size} Lucide icons (${Buffer.byteLength(bundled)} bytes).`);
}

async function main() {
  const root = path.resolve(__dirname, '..');
  process.chdir(root);
  await fs.mkdir('assets/css', { recursive: true });
  await fs.mkdir('assets/js', { recursive: true });

  const result = spawnSync(process.execPath, [
    require.resolve('tailwindcss/lib/cli.js'),
    '--config', 'tailwind.config.cjs',
    '--output', 'assets/css/tailwind.css',
    '--minify',
  ], { stdio: ['pipe', 'inherit', 'inherit'], input: '@tailwind base;\n@tailwind components;\n@tailwind utilities;\n' });
  if (result.error) throw result.error;
  if (result.status !== 0) process.exit(result.status || 1);

  const lucideRoot = path.dirname(require.resolve('lucide/package.json'));
  await buildIcons(root, lucideRoot);
  console.log('Assets built: assets/css/tailwind.css, assets/js/lucide.min.js');
}

main().catch(error => {
  console.error(error.message);
  process.exitCode = 1;
});
